pub fn streamLines(reader: anytype, allocator: Allocator, visitor: anytype) !void {
    var buf = std.ArrayList(u8).init(allocator);
    defer buf.deinit();
    const initial_capacity = 8192;
    var read_buf = try allocator.alloc(u8, initial_capacity);
    defer allocator.free(read_buf);
    while (true) {
        const bytes_read = try reader.read(read_buf);
        if (bytes_read == 0) break;
        var i: usize = 0;
        while (i < bytes_read) {
            const byte = read_buf[i];
            if (byte == '\n') {
                try visitor(buf.items);
                buf.clearRetainingCapacity();
            } else {
                try buf.append(byte);
            }
            i += 1;
        }
        if (buf.items.len > 10 * 1024 * 1024) {
            const new_capacity = initial_capacity * 2;
            if (read_buf.len < new_capacity) {
                allocator.free(read_buf);
                read_buf = try allocator.alloc(u8, new_capacity);
            }
        }
