pub const RSFConfig = struct {
    dim: usize = 256,
    layers: usize = 12,
    heads: usize = 8,
    ff_dim: usize = 1024,
    dropout: f32 = 0.1,
    activation: enum { ReLU, GeLU } = .GeLU,
    use_residual: bool = true,
    use_layer_norm: bool = true,
