pub const RSF = struct {
    config: RSFConfig,
    weights: []f32,
    allocator: Allocator,
    prng: PRNG,
    mgt: *MGT,

    pub fn init(allocator: Allocator, config: RSFConfig, mgt: *MGT) !RSF {
        var prng = PRNG.init(config.seed);
        const total_params = (config.dim * config.dim * 4) * config.layers + (config.ff_dim * config.dim * 2) * config.layers;
        const weights = try allocator.alloc(f32, total_params);
        errdefer allocator.free(weights);
        var i: usize = 0;
        while (i < total_params) : (i += 1) {
            weights[i] = prng.random().float(f32) * 2.0 - 1.0;
        }
        return RSF{
            .config = config,
            .weights = weights,
            .allocator = allocator,
            .prng = prng,
            .mgt = mgt,
        };
    }

    pub fn deinit(self: *RSF) void {
        self.allocator.free(self.weights);
    }

    pub fn forward(self: *RSF, input: *Tensor) !void {
        if (input.shape.len != 2 or input.shape[1] != self.config.dim) {
            return error.InvalidInputShape;
        }
        var batch_size = input.shape[0];
        var hidden = try self.allocator.alloc(f32, batch_size * self.config.dim);
        errdefer self.allocator.free(hidden);
        mem.copy(f32, hidden, input.data);
        var layer_idx: usize = 0;
        while (layer_idx < self.config.layers) : (layer_idx += 1) {
            try self.attentionForward(hidden, batch_size, layer_idx);
            if (self.config.use_residual) {
                try self.residualAdd(hidden, input.data, batch_size, self.config.dim);
            }
            if (self.config.use_layer_norm) {
                try self.layerNorm(hidden, batch_size, self.config.dim);
            }
            try self.feedForward(hidden, batch_size, layer_idx);
            if (self.config.use_residual) {
                try self.residualAdd(hidden, input.data, batch_size, self.config.dim);
            }
            if (self.config.use_layer_norm) {
                try self.layerNorm(hidden, batch_size, self.config.dim);
            }
        }
        mem.copy(f32, input.data, hidden);
        self.allocator.free(hidden);
    }

    fn attentionForward(self: *RSF, hidden: []f32, batch_size: usize, layer_idx: usize) !void {
        const head_dim = self.config.dim / self.config.heads;
        const q_offset = layer_idx * (self.config.dim * self.config.dim * 3);
        const k_offset = q_offset + self.config.dim * self.config.dim;
        const v_offset = k_offset + self.config.dim * self.config.dim;
        const o_offset = v_offset + self.config.dim * self.config.dim;
        var q = try self.allocator.alloc(f32, batch_size * self.config.dim);
        errdefer self.allocator.free(q);
        var k = try self.allocator.alloc(f32, batch_size * self.config.dim);
        errdefer self.allocator.free(k);
        var v = try self.allocator.alloc(f32, batch_size * self.config.dim);
        errdefer self.allocator.free(v);
        defer self.allocator.free(q);
        defer self.allocator.free(k);
        defer self.allocator.free(v);
        try self.linear(hidden, q, batch_size, self.config.dim, &self.weights[q_offset..q_offset + self.config.dim * self.config.dim]);
        try self.linear(hidden, k, batch_size, self.config.dim, &self.weights[k_offset..k_offset + self.config.dim * self.config.dim]);
        try self.linear(hidden, v, batch_size, self.config.dim, &self.weights[v_offset..v_offset + self.config.dim * self.config.dim]);
        var attn = try self.allocator.alloc(f32, batch_size * self.config.heads * self.config.heads);
        errdefer self.allocator.free(attn);
        mem.set(f32, attn, 0.0);
        var h: usize = 0;
        while (h < self.config.heads) : (h += 1) {
            var b: usize = 0;
            while (b < batch_size) : (b += 1) {
                var i: usize = 0;
                while (i < head_dim) : (i += 1) {
                    var j: usize = 0;
                    while (j < head_dim) : (j += 1) {
                        const q_val = q[(b * self.config.dim + h * head_dim + i)];
                        const k_val = k[(b * self.config.dim + h * head_dim + j)];
                        attn[(b * self.config.heads + h) * self.config.heads + h] += q_val * k_val / math.sqrt(@as(f32, @floatFromInt(head_dim)));
                    }
                }
            }
        }
        try self.softmax(attn, batch_size * self.config.heads * self.config.heads);
        var out = try self.allocator.alloc(f32, batch_size * self.config.dim);
        errdefer self.allocator.free(out);
        mem.set(f32, out, 0.0);
        defer self.allocator.free(out);
        h = 0;
        while (h < self.config.heads) : (h += 1) {
            b = 0;
            while (b < batch_size) : (b += 1) {
                var i: usize = 0;
                while (i < head_dim) : (i += 1) {
                    var j: usize = 0;
                    while (j < self.config.heads) : (j += 1) {
                        out[(b * self.config.dim + h * head_dim + i)] += attn[(b * self.config.heads + h) * self.config.heads + j] * v[(b * self.config.dim + j * head_dim + i)];
                    }
                }
            }
        }
        try self.linear(out, hidden, batch_size, self.config.dim, &self.weights[o_offset..o_offset + self.config.dim * self.config.dim]);
    }

    fn feedForward(self: *RSF, hidden: []f32, batch_size: usize, layer_idx: usize) !void {
        const ff_offset = self.config.layers * self.config.dim * self.config.dim * 4 + layer_idx * (self.config.ff_dim * self.config.dim * 2);
        var inter = try self.allocator.alloc(f32, batch_size * self.config.ff_dim);
        errdefer self.allocator.free(inter);
        mem.set(f32, inter, 0.0);
        defer self.allocator.free(inter);
        try self.linear(hidden, inter, batch_size, self.config.dim, &self.weights[ff_offset..ff_offset + self.config.dim * self.config.ff_dim]);
        var i: usize = 0;
        while (i < inter.len) : (i += 1) {
            switch (self.config.activation) {
                .ReLU => inter[i] = math.max(0.0, inter[i]),
                .GeLU => inter[i] = self.gelu(inter[i]),
            }
        }
        try self.linear(inter, hidden, batch_size, self.config.ff_dim, &self.weights[ff_offset + self.config.dim * self.config.ff_dim..ff_offset + self.config.dim * self.config.ff_dim + self.config.ff_dim * self.config.dim]);
    }

    fn linear(self: *RSF, input: []const f32, output: []f32, batch: usize, in_dim: usize, weights: []const f32) !void {
        if (weights.len != in_dim * output.len / batch) return error.InvalidWeights;
        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var i: usize = 0;
            while (i < output.len / batch) : (i += 1) {
                var sum: f32 = 0.0;
                var j: usize = 0;
                while (j < in_dim) : (j += 1) {
                    sum += input[(b * in_dim + j)] * weights[j * (output.len / batch) + i];
                }
                output[(b * (output.len / batch) + i)] = sum;
            }
        }
    }

    fn residualAdd(a: []f32, b: []const f32, batch: usize, dim: usize) !void {
        var i: usize = 0;
        while (i < batch * dim) : (i += 1) {
            a[i] += b[i];
        }
    }

    fn layerNorm(x: []f32, batch: usize, dim: usize) !void {
        var i: usize = 0;
        while (i < batch) : (i += 1) {
            var mean: f32 = 0.0;
            var j: usize = 0;
            while (j < dim) : (j += 1) {
                mean += x[(i * dim + j)] / @as(f32, @floatFromInt(dim));
            }
            var var_sum: f32 = 0.0;
            j = 0;
            while (j < dim) : (j += 1) {
                const centered = x[(i * dim + j)] - mean;
                var_sum += centered * centered / @as(f32, @floatFromInt(dim));
            }
            const stddev = math.sqrt(var_sum + 1e-6);
            j = 0;
            while (j < dim) : (j += 1) {
                x[(i * dim + j)] = (x[(i * dim + j)] - mean) / stddev;
            }
        }
    }

    fn softmax(self: *RSF, x: []f32, len: usize) !void {
        var max_val: f32 = x[0];
        var i: usize = 1;
        while (i < len) : (i += 1) {
            if (x[i] > max_val) max_val = x[i];
        }
        var sum: f32 = 0.0;
        i = 0;
        while (i < len) : (i += 1) {
            x[i] = math.exp(x[i] - max_val);
            sum += x[i];
        }
        i = 0;
        while (i < len) : (i += 1) {
            x[i] /= sum;
        }
    }

    fn gelu(self: *RSF, x: f32) f32 {
        _ = self;
        const sqrt2 = math.sqrt(2.0);
        const erf_val = math.erf(x / sqrt2);
        return 0.5 * x * (1.0 + erf_val);
    }
};

test "RSF forward" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    var mgt = try MGT.init(allocator);
    defer mgt.deinit();
    var config = RSFConfig{ .dim = 64, .layers = 2, .heads = 4 };
    var rsf = try RSF.init(allocator, config, &mgt);
    defer rsf.deinit();
    var tensor = try Tensor.init(allocator, &.{1, 64});
    defer tensor.deinit();
    mem.set(f32, tensor.data, 0.5);
    try rsf.forward(&tensor);
    try std.testing.expectEqual(@as(f32, 0.5), tensor.data[0]);
}
