const std = @import("std");
const mem = std.mem;
const math = std.math;
const crypto = std.crypto;
const Allocator = mem.Allocator;
const TensorType = enum { F32, F64, I32, U32, BOOL };
const Shape = []usize;

pub const Tensor = struct {
    data: []f32,
    shape: Shape,
    strides: ?Shape = null,
    allocator: Allocator,
    dtype: TensorType = .F32,

    pub fn init(allocator: Allocator, shape: Shape) !Tensor {
        if (shape.len == 0) return error.EmptyShape;
        var total_size: usize = 1;
        for (shape) |dim| {
            total_size *= dim;
        }
        var data = try allocator.alloc(f32, total_size);
        errdefer allocator.free(data);
        mem.set(f32, data, 0.0);
        var strides = try allocator.alloc(usize, shape.len);
        errdefer allocator.free(strides);
        var stride: usize = 1;
        var i: usize = shape.len;
        while (i > 0) {
            i -= 1;
            strides[i] = stride;
            stride *= shape[i];
        }
        return Tensor{
            .data = data,
            .shape = try allocator.dupe(usize, shape),
            .strides = strides,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape);
        if (self.strides) |s| {
            self.allocator.free(s);
        }
    }

    pub fn reshape(self: *Tensor, new_shape: Shape) !void {
        var total: usize = 1;
        for (new_shape) |dim| {
            total *= dim;
        }
        if (total != self.numElements()) {
            return error.ShapeMismatch;
        }
        self.allocator.free(self.shape);
        self.shape = try self.allocator.dupe(usize, new_shape);
        self.allocator.free(self.strides.?);
        self.strides = null;
        var stride: usize = 1;
        var i: usize = new_shape.len;
        while (i > 0) {
            i -= 1;
            self.strides = try self.allocator.alloc(usize, new_shape.len);
            self.strides.?[i] = stride;
            stride *= new_shape[i];
        }
    }

    pub fn numElements(self: *const Tensor) usize {
        var total: usize = 1;
        for (self.shape) |dim| {
            total *= dim;
        }
        return total;
    }

    pub fn at(self: *const Tensor, indices: []usize) f32 {
        if (indices.len != self.shape.len) unreachable;
        var offset: usize = 0;
        var i: usize = 0;
        while (i < indices.len) : (i += 1) {
            if (indices[i] >= self.shape[i]) unreachable;
            offset += indices[i] * self.strides.?[i];
        }
        return self.data[offset];
    }

    pub fn set(self: *Tensor, indices: []usize, value: f32) void {
        if (indices.len != self.shape.len) unreachable;
        var offset: usize = 0;
        var i: usize = 0;
        while (i < indices.len) : (i += 1) {
            if (indices[i] >= self.shape[i]) unreachable;
            offset += indices[i] * self.strides.?[i];
        }
        self.data[offset] = value;
    }

    pub fn add(self: *Tensor, other: *const Tensor) !void {
        if (!self.shapeMatches(other)) return error.ShapeMismatch;
        var i: usize = 0;
        while (i < self.data.len) : (i += 1) {
            self.data[i] += other.data[i];
        }
    }

    pub fn mul(self: *Tensor, other: *const Tensor) !void {
        if (!self.shapeMatches(other)) return error.ShapeMismatch;
        var i: usize = 0;
        while (i < self.data.len) : (i += 1) {
            self.data[i] *= other.data[i];
        }
    }

    pub fn matmul(self: *Tensor, other: *const Tensor) !Tensor {
        if (self.shape.len != 2 or other.shape.len != 2 or self.shape[1] != other.shape[0]) {
            return error.InvalidMatrixDimensions;
        }
        const m = self.shape[0];
        const n = other.shape[1];
        const k = self.shape[1];
        var result_shape = try self.allocator.alloc(usize, 2);
        result_shape[0] = m;
        result_shape[1] = n;
        var result = try Tensor.init(self.allocator, result_shape);
        errdefer result.deinit();
        var i: usize = 0;
        while (i < m) : (i += 1) {
            var j: usize = 0;
            while (j < n) : (j += 1) {
                var sum: f32 = 0.0;
                var l: usize = 0;
                while (l < k) : (l += 1) {
                    sum += self.at(&.{i, l}) * other.at(&.{l, j});
                }
                try result.set(&.{i, j}, sum);
            }
        }
        return result;
    }

    fn shapeMatches(self: *const Tensor, other: *const Tensor) bool {
        if (self.shape.len != other.shape.len) return false;
        var i: usize = 0;
        while (i < self.shape.len) : (i += 1) {
            if (self.shape[i] != other.shape[i]) return false;
        }
        return true;
    }

    pub fn transpose(self: *Tensor) !Tensor {
        if (self.shape.len != 2) return error.NotMatrix;
        var new_shape = try self.allocator.alloc(usize, 2);
        new_shape[0] = self.shape[1];
        new_shape[1] = self.shape[0];
        var result = try Tensor.init(self.allocator, new_shape);
        errdefer result.deinit();
        var i: usize = 0;
        while (i < self.shape[0]) : (i += 1) {
            var j: usize = 0;
            while (j < self.shape[1]) : (j += 1) {
                try result.set(&.{j, i}, self.at(&.{i, j}));
            }
        }
        return result;
    }

    pub fn sum(self: *const Tensor, axis: ?usize) !Tensor {
        if (axis) |a| {
            if (a >= self.shape.len) return error.InvalidAxis;
        }
        const original_shape = try self.allocator.dupe(usize, self.shape);
        defer self.allocator.free(original_shape);
        if (axis) |a| {
            original_shape[a] = 1;
        }
        var new_shape_len: usize = 0;
        for (original_shape) |dim| {
            if (dim > 1) new_shape_len += 1;
        }
        var new_shape = try self.allocator.alloc(usize, new_shape_len);
        errdefer self.allocator.free(new_shape);
        var idx: usize = 0;
        for (original_shape) |dim| {
            if (dim > 1) {
                new_shape[idx] = dim;
                idx += 1;
            }
        }
        var result = try Tensor.init(self.allocator, new_shape);
        errdefer result.deinit();
        if (axis == null) {
            var total: f32 = 0.0;
            for (self.data) |val| {
                total += val;
            }
            result.set(&.{}, total);
        } else {
            const a = axis.?;
            var indices = try self.allocator.alloc(usize, self.shape.len);
            errdefer self.allocator.free(indices);
            mem.set(usize, indices, 0);
            while (true) {
                var sum: f32 = 0.0;
                var start = indices[a];
                var end = if (a + 1 < self.shape.len) self.shape[a + 1] else 1;
                var l: usize = 0;
                while (l < self.shape[a]) : (l += 1) {
                    indices[a] = l;
                    sum += self.at(indices);
                }
                var result_idx: usize = 0;
                var k: usize = 0;
                while (k < self.shape.len) : (k += 1) {
                    if (k != a and indices[k] > 0) {
                        result_idx += 1;
                    }
                }
                try result.set(&result.shape[0..new_shape_len], sum);
                indices[a] = start;
                var carry: bool = true;
                var pos: usize = 0;
                while (carry and pos < self.shape.len) : (pos += 1) {
                    if (pos == a) continue;
                    if (indices[pos] < self.shape[pos] - 1) {
                        indices[pos] += 1;
                        carry = false;
                    } else {
                        indices[pos] = 0;
                    }
                }
                if (carry) break;
            }
            self.allocator.free(indices);
        }
        return result;
    }
};

