const std = @import("std");
const mem = std.mem;
const math = std.math;
const crypto = std.crypto;
const Allocator = mem.Allocator;
const types = @import("../core/types.zig");

const VocabSize = 50257;
const MaxContext = 2048;
const MaxTokens = 256;

pub const MGTConfig = struct {
    vocab_size: usize = VocabSize,
    max_context: usize = MaxContext,
    max_tokens: usize = MaxTokens,
    seed: u64 = 42,
};

pub const MGT = struct {
    config: MGTConfig,
    vocab: []u8,
    bpe_ranks: []u32,
    merges: [][]u8,
    allocator: Allocator,
    prng: types.PRNG,

    pub fn init(allocator: Allocator, config: ?MGTConfig) !MGT {
        var cfg = config orelse MGTConfig{};
        var prng = types.PRNG.init(cfg.seed);
        const vocab = try allocator.alloc(u8, cfg.vocab_size * 4);
        errdefer allocator.free(vocab);
        mem.set(u8, vocab, 0);
        const bpe_ranks = try allocator.alloc(u32, cfg.vocab_size);
        errdefer allocator.free(bpe_ranks);
        var i: usize = 0;
        while (i < cfg.vocab_size) : (i += 1) {
            bpe_ranks[i] = @as(u32, @intCast(i));
        }
        var merges = try allocator.alloc([]u8, 10000);
        errdefer {
            for (merges[0..i]) |merge| allocator.free(merge);
            allocator.free(merges);
        }
        i = 0;
        while (i < merges.len) : (i += 1) {
            const pair_len = 8;
            var pair = try allocator.alloc(u8, pair_len);
            mem.set(u8, pair, @as(u8, @truncate(i)));
            merges[i] = pair;
        }
        return MGT{
            .config = cfg,
            .vocab = vocab,
            .bpe_ranks = bpe_ranks,
            .merges = merges,
            .allocator = allocator,
            .prng = prng,
        };
    }

    pub fn deinit(self: *MGT) void {
        for (self.merges) |merge| {
            self.allocator.free(merge);
        }
        self.allocator.free(self.merges);
        self.allocator.free(self.bpe_ranks);
        self.allocator.free(self.vocab);
    }

    pub fn encode(self: *MGT, text: []const u8, tokens: *std.ArrayList(u32)) !void {
        if (text.len == 0) return;
        tokens.clearRetainingCapacity();
        var current_word = std.ArrayList(u8).init(self.allocator);
        defer current_word.deinit();
        var i: usize = 0;
        while (i < text.len) : (i += 1) {
            if (text[i] == ' ') {
                if (current_word.items.len > 0) {
                    try self.bpeEncode(&current_word, tokens);
                    current_word.clearRetainingCapacity();
                }
                try tokens.append(self.vocab_size - 1);
            } else {
                try current_word.append(text[i]);
            }
        }
        if (current_word.items.len > 0) {
            try self.bpeEncode(&current_word, tokens);
        }
        if (tokens.items.len > self.config.max_context) {
            tokens.shrinkRetainingCapacity(self.config.max_context);
        }
    }

    fn bpeEncode(self: *MGT, word: *std.ArrayList(u8), tokens: *std.ArrayList(u32)) !void {
        if (word.items.len == 0) return;
        var ids = try self.allocator.alloc(u32, word.items.len);
        errdefer self.allocator.free(ids);
        var j: usize = 0;
        while (j < word.items.len) : (j += 1) {
            ids[j] = @as(u32, @intCast(word.items[j]));
        }
        while (ids.len > 1) {
            var merge_score: u32 = std.math.maxInt(u32);
            var merge_idx: usize = 0;
            var k: usize = 0;
            while (k < ids.len - 1) : (k += 1) {
                const pair = ids[k] * 256 + ids[k + 1];
                const rank = self.getRank(pair);
                if (rank < merge_score) {
                    merge_score = rank;
                    merge_idx = k;
                }
            }
            if (merge_score >= std.math.maxInt(u32)) break;
            const new_id = self.merges[merge_idx][0] * 256 + self.merges[merge_idx][1];
            ids[merge_idx] = new_id;
            var temp = try self.allocator.alloc(u32, ids.len - 1);
            errdefer self.allocator.free(temp);
            mem.copy(u32, temp[0..merge_idx], ids[0..merge_idx]);
            mem.copy(u32, temp[merge_idx..ids.len - 1], ids[merge_idx + 1 ..]);
            self.allocator.free(ids);
            ids = temp;
        }
        try tokens.appendSlice(ids);
        self.allocator.free(ids);
    }

    fn getRank(self: *MGT, pair: u64) u32 {
        const idx = @as(usize, @intCast(pair % self.bpe_ranks.len));
        return self.bpe_ranks[idx];
    }

    pub fn decode(self: *MGT, tokens: []const u32, allocator: Allocator) ![]u8 {
        if (tokens.len == 0) return try allocator.alloc(u8, 0);
        var text = std.ArrayList(u8).init(allocator);
        errdefer text.deinit();
        var prev_token: u32 = 0;
        for (tokens) |token| {
            if (token == self.config.vocab_size - 1) {
                try text.append(' ');
                continue;
            }
            var word = try self.tokenToBytes(token, allocator);
            defer allocator.free(word);
            if (prev_token != 0 and self.isContinuation(prev_token, token)) {
                try text.appendSlice(word[1..]);
            } else {
                try text.appendSlice(word);
            }
            prev_token = token;
        }
        return try text.toOwnedSlice();
    }

    fn tokenToBytes(self: *MGT, token: u32, allocator: Allocator) ![]u8 {
        var bytes = try allocator.alloc(u8, 8);
        var temp = token;
        var i: usize = 0;
        while (temp > 0 and i < 8) : (i += 1) {
            bytes[i] = @as(u8, @truncate(temp));
            temp >>= 8;
        }
        return bytes[0..i];
    }

    fn isContinuation(self: *MGT, prev: u32, curr: u32) bool {
        return (curr >> 8) == (prev & 0xFF);
    }
};

