const std = @import("std");
const mem = std.mem;
const math = std.math;
const Allocator = mem.Allocator;

pub const RankerConfig = struct {
    top_k: usize = 50,
    top_p: f32 = 0.9,
    temperature: f32 = 1.0,
    repetition_penalty: f32 = 1.1,
    max_length: usize = 256,
};

pub const Ranker = struct {
    config: RankerConfig,
    allocator: Allocator,

    pub fn init(allocator: Allocator, config: RankerConfig) Ranker {
        return Ranker{
            .config = config,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Ranker) void {
        _ = self;
    }

    pub fn rank(self: *Ranker, logits: []f32, past_tokens: []u32) ![]u32 {
        var scores = try self.allocator.alloc(f32, logits.len);
        errdefer self.allocator.free(scores);
        mem.copy(f32, scores, logits);
        var i: usize = 0;
        while (i < past_tokens.len and i < 100) : (i += 1) {
            const token = past_tokens[past_tokens.len - 1 - i];
            if (token < scores.len) {
                scores[token] /= self.config.repetition_penalty;
            }
        }
        var i_f32: f32 = self.config.temperature;
        if (i_f32 > 0.0) {
            var j: usize = 0;
            while (j < scores.len) : (j += 1) {
                scores[j] /= i_f32;
            }
        }
        try self.softmaxInPlace(scores, scores.len);
        var candidates = try self.allocator.alloc(u32, 0);
        errdefer self.allocator.free(candidates);
        var cumsum: f32 = 0.0;
        var k: usize = 0;
        while (k < scores.len) : (k += 1) {
            cumsum += scores[k];
            if (cumsum > 1.0 - self.config.top_p) break;
            var temp = try self.allocator.alloc(u32, candidates.len + 1);
            errdefer self.allocator.free(temp);
            mem.copy(u32, temp[0..candidates.len], candidates);
            temp[candidates.len] = @as(u32, @intCast(k));
            self.allocator.free(candidates);
            candidates = temp;
        }
        if (candidates.len > self.config.top_k) {
            var temp = try self.allocator.alloc(u32, self.config.top_k);
            errdefer self.allocator.free(temp);
            var prng = std.rand.DefaultPrng.init(42);
            var rng = prng.random();
            mem.copy(u32, temp, candidates[0..self.config.top_k]);
            self.allocator.free(candidates);
            candidates = temp;
        }
        return candidates;
    }

    fn softmaxInPlace(self: *Ranker, x: []f32, len: usize) !void {
        _ = self;
        var max_val: f32 = x[0];
        var i: usize = 1;
        while (i < len) : (i += 1) {
            if (x[i] > max_val) max_val = x[i];
        }
        var sum: f32 = 0.0;
        i = 0;
        while (i < len) : (i += 1) {
            x[i] = math.exp(x[i] - max_val);
            sum += x[i];
        }
        i = 0;
        while (i < len) : (i += 1) {
            x[i] /= sum;
        }
    }
};

test "Ranker top-k" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    var config = RankerConfig{ .top_k = 3 };
    var ranker = Ranker.init(allocator, config);
    defer ranker.deinit();
    var logits = [_]f32{ 1.0, 2.0, 3.0, 0.5, 4.0 };
    var past = [_]u32{ 1, 2 };
    var candidates = try ranker.rank(&logits, &past);
