    rsf: ?*RSF = null,
    allocator: Allocator,
};

pub fn importModel(path: []const u8, allocator: Allocator) !ModelFormat {
    var file = try fs.cwd().openFile(path, .{});
    defer file.close();
    var header = [8]u8{0};
    _ = try file.readAll(&header);
    if (!mem.eql(u8, &header, "JAIDEv1")) return error.InvalidFormat;
    var config_len_bytes = [4]u8{0};
    _ = try file.readAll(&config_len_bytes);
    const config_len = mem.readIntBig(u32, &config_len_bytes);
    var config = try allocator.alloc(u8, @as(usize, @intCast(config_len)));
    errdefer allocator.free(config);
    _ = try file.readAll(config);
    var metadata_len_bytes = [4]u8{0};
    _ = try file.readAll(&metadata_len_bytes);
    const metadata_len = mem.readIntBig(u32, &metadata_len_bytes);
    var metadata = try allocator.alloc(u8, @as(usize, @intCast(metadata_len)));
    errdefer allocator.free(metadata);
    _ = try file.readAll(metadata);
    var weights_len_bytes = [8]u8{0};
    _ = try file.readAll(&weights_len_bytes);
    const weights_len = mem.readIntBig(u64, &weights_len_bytes);
    var weights = try allocator.alloc(f32, @as(usize, @intCast(weights_len / 4)));
    errdefer allocator.free(weights);
    var read_bytes: usize = 0;
    while (read_bytes < weights.len * 4) {
        const chunk = try file.readAll(weights[read_bytes / 4 ..]);
        read_bytes += chunk;
        if (chunk == 0) break;
    }
    if (read_bytes != weights.len * 4) return error.IncompleteRead;
    var mgt: ?*MGT = null;
    var rsf: ?*RSF = null;
    var config_str = std.mem.span(config);
    if (mem.containsAtLeast(u8, config_str, 1, "mgt")) {
        mgt = try MGT.init(allocator, null);
    }
    if (mem.containsAtLeast(u8, config_str, 1, "rsf")) {
        var cfg = RSFConfig{};
        rsf = try RSF.init(allocator, cfg, if (mgt) |m| m else unreachable);
    }
    return ModelFormat{
        .weights = weights,
        .config = config,
        .metadata = metadata,
        .mgt = mgt,
        .rsf = rsf,
        .allocator = allocator,
    };
}

pub fn freeLoadedModel(model: *ModelFormat) void {
    if (model.mgt) |mgt| {
        mgt.deinit();
    }
    if (model.rsf) |rsf| {
        rsf.deinit();
    }
    model.allocator.free(model.weights);
    model.allocator.free(model.config);
    model.allocator.free(model.metadata);
}
