const std = @import("std");
const mem = std.mem;
const math = std.math;
const Allocator = mem.Allocator;
const types = @import("types.zig");

pub const SSIConfig = struct {
    max_vectors: usize = 1000000,
    dim: usize = 256,
    max_distance: f32 = 1.0,
    probe_size: usize = 32,
    ef_construction: usize = 200,
    ef_search: usize = 50,
};

pub const VectorNode = struct {
    vector: [256]f32,
    id: u64,
    distance: f32,
    next: ?*VectorNode = null,
};

pub const SSINode = struct {
    vectors: ?*VectorNode = null,
    children: [8]?*SSINode = [_]?*SSINode{null} ** 8,
    bounding_radius: f32 = 0.0,
    center: [256]f32 = [_]f32{0.0} ** 256,
};

pub const SSI = struct {
    config: SSIConfig,
    root: ?*SSINode = null,
    vectors: std.ArrayList(VectorNode),
    allocator: Allocator,

    pub fn init(allocator: Allocator, config: SSIConfig) !SSI {
        return SSI{
            .config = config,
            .vectors = std.ArrayList(VectorNode).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *SSI) void {
        self.vectors.deinit();
        if (self.root) |root| {
            self.freeNode(root);
        }
    }

    fn freeNode(self: *SSI, node: *SSINode) void {
        if (node.vectors) |vec| {
            self.allocator.destroy(vec);
        }
        for (node.children) |child| {
            if (child) |c| {
                self.freeNode(c);
            }
        }
        self.allocator.destroy(node);
    }

    pub fn add(self: *SSI, vector: [256]f32, id: u64) !void {
        if (self.vectors.items.len >= self.config.max_vectors) return error.MaxVectorsReached;
        var vec_node = try self.allocator.create(VectorNode);
        vec_node.* = .{ .vector = vector, .id = id, .distance = 0.0 };
        try self.vectors.append(vec_node.*);
        if (self.root == null) {
            self.root = try self.buildNode(&.{vec_node.*}, .{});
        } else {
            try self.insertIntoTree(self.root.?, vec_node);
        }
    }

    fn insertIntoTree(self: *SSI, node: *SSINode, vec: *VectorNode) !void {
        const dist = self.distance(vec.vector, node.center);
        if (dist < node.bounding_radius) {
            if (node.vectors == null) {
                node.vectors = vec;
            } else {
                var i: usize = 0;
                while (i < 8) : (i += 1) {
                    if (node.children[i] == null) {
                        node.children[i] = try self.allocator.create(SSINode);
                        node.children[i].?.* = .{ .center = self.averageCenter(&.{vec.vector}), .bounding_radius = 0.1 };
                        try self.insertIntoTree(node.children[i].?, vec);
                        return;
                    }
                }
                return error.NodeFull;
            }
        }
        node.bounding_radius = math.max(node.bounding_radius, dist);
        node.center = self.updateCenter(node, vec.vector);
    }

    fn buildNode(self: *SSI, vectors: []VectorNode, center: [256]f32) !*SSINode {
        var node = try self.allocator.create(SSINode);
        node.* = SSINode{ .center = center, .bounding_radius = 0.0 };
        if (vectors.len == 1) {
            node.vectors = &vectors[0];
            var dist = self.distance(vectors[0].vector, center);
            node.bounding_radius = dist;
            return node;
        }
        var i: usize = 0;
        while (i < 8 and vectors.len > 1) : (i += 1) {
            var child_vectors = self.splitVectors(vectors, i);
            if (child_vectors.len > 0) {
                const child_center = self.averageCenter(child_vectors);
                node.children[i] = try self.buildNode(child_vectors, child_center);
            }
        }
        if (node.vectors == null) {
            var max_dist: f32 = 0.0;
            var closest: usize = 0;
            var j: usize = 0;
            while (j < vectors.len) : (j += 1) {
                const d = self.distance(vectors[j].vector, center);
                if (d > max_dist) {
                    max_dist = d;
                    closest = j;
                }
            }
            node.vectors = &vectors[closest];
            node.bounding_radius = max_dist;
        }
        return node;
    }

    fn splitVectors(self: *SSI, vectors: []VectorNode, split_idx: usize) []VectorNode {
        _ = self;
        _ = split_idx;
        var left_len: usize = vectors.len / 2;
        return vectors[0..left_len];
    }

    fn averageCenter(self: *SSI, vectors: []const [256]f32) [256]f32 {
        var center = [_]f32{0.0} ** 256;
        var count: usize = vectors.len;
        if (count == 0) return center;
        var d: usize = 0;
        while (d < 256) : (d += 1) {
            var sum: f32 = 0.0;
            for (vectors) |vec| {
                sum += vec[d];
            }
            center[d] = sum / @as(f32, @floatFromInt(count));
        }
        return center;
    }

    fn updateCenter(self: *SSI, node: *SSINode, new_vec: [256]f32) [256]f32 {
        _ = self;
        var count: f32 = 1.0;
        var center = node.center;
        var d: usize = 0;
        while (d < 256) : (d += 1) {
            center[d] = (center[d] * (count - 1.0) + new_vec[d]) / count;
        }
        return center;
    }

    fn distance(self: *SSI, a: [256]f32, b: [256]f32) f32 {
        var dist: f32 = 0.0;
        var i: usize = 0;
        while (i < 256) : (i += 1) {
            const diff = a[i] - b[i];
            dist += diff * diff;
        }
        return math.sqrt(dist);
    }

    pub fn search(self: *SSI, query: [256]f32, k: usize) ![]u64 {
        var results = std.ArrayList(u64).init(self.allocator);
        errdefer results.deinit();
        if (self.root) |root| {
            try self.searchNode(root, query, k, &results);
        }
        if (results.items.len > k) {
            var prng = std.rand.DefaultPrng.init(42);
            var rng = prng.random();
            var i: usize = k;
            while (i < results.items.len) : (i += 1) {
                if (rng.float(f32) > @as(f32, @floatFromInt(k)) / @as(f32, @floatFromInt(i))) {
                    results.items[i] = results.items[k];
                    results.items[k] = results.items[i];
                    k += 1;
                }
            }
            results.shrinkRetainingCapacity(k);
        }
        return try results.toOwnedSlice();
    }

    fn searchNode(self: *SSI, node: *SSINode, query: [256]f32, k: usize, results: *std.ArrayList(u64)) !void {
        const dist = self.distance(query, node.center);
        if (dist > node.bounding_radius + self.config.max_distance) return;
        if (node.vectors) |vec| {
            if (results.items.len < k or dist < self.config.max_distance) {
                try results.append(vec.id);
            }
        }
        var i: usize = 0;
        while (i < 8) : (i += 1) {
            if (node.children[i]) |child| {
                try self.searchNode(child, query, k, results);
            }
        }
    }
};

test "SSI add search" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    var config = SSIConfig{};
    var ssi = try SSI.init(allocator, config);
    defer ssi.deinit();
    var vec1: [256]f32 = [_]f32{1.0} ** 256;
    try ssi.add(vec1, 1);
    var query = vec1;
    var results = try ssi.search(query, 1);
    defer allocator.free(results);
    try std.testing.expectEqual(@as(usize, 1), results.len);
    try std.testing.expectEqual(@as(u64, 1), results[0]);
}
