const std = @import("std");
const mem = std.mem;

pub const PRNG = struct {
    state: [4]u64,

    pub fn init(seed: u64) PRNG {
        var s = [_]u64{ 0, 0, 0, 0 };
        var x = splitmix64(seed);
        s[0] = x;
        x = splitmix64(x);
        s[1] = x;
        x = splitmix64(x);
        s[2] = x;
        x = splitmix64(x);
        s[3] = x;
        return .{ .state = s };
    }

    fn splitmix64(z0: u64) u64 {
        var z = z0 +% 0x9E3779B97F4A7C15;
        z = (z ^ (z >> 30)) *% 0xBF58476D1CE4E5B9;
        z = (z ^ (z >> 27)) *% 0x94D049BB133111EB;
        return z ^ (z >> 31);
    }

    fn rotl(x: u64, k: u6) u64 {
        return (x << k) | (x >> @intCast(64 - k));
    }

    fn next64(self: *PRNG) u64 {
        const result = rotl(self.state[0] +% self.state[3], 23) +% self.state[0];
        const t = self.state[1] << 17;
        self.state[2] ^= self.state[0];
        self.state[3] ^= self.state[1];
        self.state[1] ^= self.state[2];
        self.state[0] ^= self.state[3];
        self.state[2] ^= t;
        self.state[3] = rotl(self.state[3], 45);
        return result;
    }

    pub fn float(self: *PRNG, comptime T: type) T {
        if (@typeInfo(T) != .Float) @compileError("T must be float");
        const u = self.next64() >> 11;
        const f = @as(f64, @floatFromInt(u)) * (1.0 / 9007199254740992.0);
        return @as(T, @floatCast(f));
    }

    pub fn uintLessThan(self: *PRNG, comptime T: type, bound: T) T {
        if (@typeInfo(T) != .Int and @typeInfo(T) != .ComptimeInt) @compileError("T must be int");
        if (bound == 0) return 0;
        const r: u64 = self.next64();
        if (@bitSizeOf(T) <= 32) {
            const m = @as(u32, @intCast(r & 0xFFFFFFFF));
            return @as(T, @intCast(@as(u64, m) % @as(u64, @intCast(bound))));
        } else {
            return @as(T, @intCast(r % @as(u64, @intCast(bound))));
        }
    }

    pub fn bytes(self: *PRNG, out: []u8) void {
        var i: usize = 0;
        while (i < out.len) : (i += 8) {
            const v = self.next64();
            const n = @min(out.len - i, 8);
            var j: usize = 0;
            while (j < n) : (j += 1) {
                out[i + j] = @as(u8, @truncate(v >> @intCast(8 * j)));
            }
        }
    }
};

pub fn f32FromBEBytes4(b: *const [4]u8) f32 {
    const u = mem.readIntBig(u32, b);
    return @bitCast(u);
}

pub fn f32ToBEBytes4(x: f32) [4]u8 {
    var b: [4]u8 = undefined;
    mem.writeInt(u32, &b, @bitCast(x), .big);
    return b;
}

pub fn u64FromBEBytes8(b: *const [8]u8) u64 {
    return mem.readIntBig(u64, b);
}

pub fn u32FromBEBytes4(b: *const [4]u8) u32 {
    return mem.readIntBig(u32, b);
}

pub fn writeBEu32(buf: []u8, v: u32) void {
    if (buf.len < 4) return;
    mem.writeInt(u32, buf[0..4], v, .big);
}

pub fn writeBEu64(buf: []u8, v: u64) void {
    if (buf.len < 8) return;
    mem.writeInt(u64, buf[0..8], v, .big);
}

pub fn ceilDiv(a: usize, b: usize) usize {
    return (a + b - 1) / b;
}

pub fn alignUp(x: usize, a: usize) usize {
    return std.mem.alignForward(usize, x, a);
}

pub fn isPowerOfTwo(x: usize) bool {
    return x != 0 and (x & (x - 1)) == 0;
}
