// path: core/model_io.zig
const std = @import("std");
const mem = std.mem;
const fs = std.fs;

const Tensor = @import("tensor.zig").Tensor;
const MGT = @import("../tokenizer/mgt.zig").MGT;
const RSF = @import("../processor/rsf.zig").RSF;
const RSFConfig = @import("../processor/rsf.zig").RSFConfig;
const types = @import("types.zig");

pub const ModelFormat = struct {
    weights: []f32,
    config: []u8,
    metadata: []u8,
    mgt: ?*MGT = null,
    rsf: ?*RSF = null,
    allocator: std.mem.Allocator,
};

pub fn importModel(path: []const u8, allocator: std.mem.Allocator) !ModelFormat {
    var file = try fs.cwd().openFile(path, .{});
    errdefer file.close();

    var header: [7]u8 = undefined;
    try file.readNoEof(&header);
    if (!mem.eql(u8, &header, "JAIDEv1")) return error.InvalidFormat;

    var u32buf: [4]u8 = undefined;
    try file.readNoEof(&u32buf);
    const config_len = mem.readIntBig(u32, &u32buf);

    var config = try allocator.alloc(u8, config_len);
    errdefer allocator.free(config);
    try file.readNoEof(config);

    try file.readNoEof(&u32buf);
    const metadata_len = mem.readIntBig(u32, &u32buf);

    var metadata = try allocator.alloc(u8, metadata_len);
    errdefer allocator.free(metadata);
    try file.readNoEof(metadata);

    var u64buf: [8]u8 = undefined;
    try file.readNoEof(&u64buf);
    const weights_bytes_len = mem.readIntBig(u64, &u64buf);
    if (weights_bytes_len % 4 != 0) return error.MisalignedWeights;

    const f32_count = @as(usize, @intCast(weights_bytes_len / 4));
    var weights = try allocator.alloc(f32, f32_count);
    errdefer allocator.free(weights);

    var chunk: [1 << 16]u8 = undefined;
    var filled: usize = 0;
    while (filled < f32_count) {
        const remaining_bytes = (f32_count - filled) * 4;
        const read_bytes = try file.read(chunk[0..@min(chunk.len, remaining_bytes)]);
        if (read_bytes == 0) break;
        if (read_bytes % 4 != 0) return error.PartialFloatRead;
        var i: usize = 0;
        while (i < read_bytes) : (i += 4) {
            const v = mem.readIntBig(u32, chunk[i .. i + 4]);
            weights[filled] = @bitCast(v);
            filled += 1;
        }
    }
    if (filled != f32_count) return error.IncompleteRead;

    var mgt: ?*MGT = null;
    var rsf: ?*RSF = null;

    if (mem.indexOf(u8, config, "mgt") != null) {
        var m = try allocator.create(MGT);
        m.* = try MGT.init(allocator, null);
        mgt = m;
    }

    if (mem.indexOf(u8, config, "rsf") != null) {
        if (mgt == null) return error.MissingMGTForRSF;
        var rsf_cfg = RSFConfig{};
        var r = try allocator.create(RSF);
        r.* = try RSF.init(allocator, rsf_cfg, mgt.?);
        rsf = r;
    }

    return .{
        .weights = weights,
        .config = config,
        .metadata = metadata,
        .mgt = mgt,
        .rsf = rsf,
        .allocator = allocator,
    };
}

pub fn freeLoadedModel(model: *ModelFormat) void {
    if (model.mgt) |m| {
        m.deinit();
        model.allocator.destroy(m);
        model.mgt = null;
    }
    if (model.rsf) |r| {
        r.deinit();
        model.allocator.destroy(r);
        model.rsf = null;
    }
    model.allocator.free(model.weights);
    model.allocator.free(model.config);
    model.allocator.free(model.metadata);
}
